const { Plugin, ItemView, Notice, PluginSettingTab, Setting } = require('obsidian');
const { spawn, spawnSync } = require('child_process');
const { existsSync, mkdirSync, writeFileSync, readFileSync } = require('fs');
const { join, dirname } = require('path');
const { homedir } = require('os');

const VIEW_TYPE = 'dsh-obsidian-math-view';
const PRESET_NAME = 'obsidian';
const EMBEDDED_PRESET = JSON.parse("{\"preset.yml\":\"name: Obsidian 笔记助手\\ndescription: 只保留文件读写与搜索的最小 agent：跨会话记忆注入、笔记写作工作流、关键想法主动捕获与备忘录。\\norder: 1\\n\",\"agent.cordis.yml\":\"# The `obsidian` agent preset: a deliberately minimal knowledge-base agent.\\n#\\n# Tools kept to the bare essentials the user asked for:\\n#   - tool-fs          read/write/edit files inside the Obsidian vault\\n#   - tool-fs-search   search/glob inside the vault\\n#   - tool-ask-user    ask before capturing key ideas, big edits, etc.\\n# Everything else (shell, web, subagents, workflows, goals, todo, ...) is\\n# deliberately NOT mounted in this preset.\\n#\\n# This file is an AGENT-PLANE composition. The roster mounts it once under a\\n# standing scope; every session naming it joins by scope parentage.\\n\\n# ── identity ────────────────────────────────────────────────────────────────\\n\\n# The deployment persona is shadowed for this agent. We do NOT use\\n# `complete: true` because the obsidian-memory plugin below appends its\\n# per-request memory section during system-prompt assembly, and a complete\\n# persona would discard every other section.\\n- id: persona\\n  name: '@deepseek-ai/dsh-persona'\\n  config:\\n    text: >-\\n      You are the user's long-term Obsidian knowledge-base assistant for\\n      mathematical (and adjacent: statistics, economics, R/LaTeX) notes and\\n      research thinking, powered by the {{model}} model. Your working\\n      directory is the user's Obsidian vault: {{cwd}}.\\n\\n      You are a thinking-and-writing partner, not a general coding agent:\\n      read the user's notes before answering, keep their notation and\\n      theoretical preferences, surface key ideas worth capturing, and keep a\\n      durable memory so future conversations start from where the last one\\n      ended. You may only read and modify files inside the vault through the\\n      provided file tools. For every significant piece of new information\\n      about the user's interests, terminology, or preferences, update the\\n      memory files under `.deepseek/` (see AGENTS.md in the vault root for\\n      the exact protocol). Never invent facts about the user's notes; read\\n      first.\\n\\n- id: agent-instructions\\n  name: '@deepseek-ai/dsh-agent-instructions'\\n  config:\\n    maxBytes: 65536\\n\\n# ── minimal tools ───────────────────────────────────────────────────────────\\n\\n- id: tool-fs\\n  name: '@deepseek-ai/dsh-tool-fs'\\n\\n- id: tool-fs-search\\n  name: '@deepseek-ai/dsh-tool-fs-search'\\n  config:\\n    sampleOverCapGlobResults: false\\n\\n# Asking the user is part of the key-idea capture contract: propose first,\\n# write to the memo only after consent (or an explicit standing consent).\\n- id: tool-ask-user\\n  name: '@deepseek-ai/dsh-tool-ask-user'\\n\\n# ── cross-session memory injection ──────────────────────────────────────────\\n\\n# Local plugin: reads the vault's `.deepseek/memory/*` and `.deepseek/inbox/*`\\n# plus a cached index distilled from this machine's past dsh sessions, and\\n# appends one bounded memory section to every system prompt of this agent.\\n- id: obsidian-memory\\n  name: ./obsidian-memory.mjs\\n  config:\\n    # 留空 = 路径无关：vault 自动取会话 cwd，sessions 自动取 $DSH_HOME/sessions。\\n    # 也可用 DSH_OBSIDIAN_VAULT / DSH_SESSIONS_ROOT 环境变量覆盖。\\n    vaultRoot: ''\\n    sessionsRoot: ''\\n    maxHistoryEntries: 40\\n    maxHistoryChars: 8000\\n    cacheTtlMs: 0\\n\",\"obsidian-memory.mjs\":\"/**\\n * obsidian-memory — cross-session memory injection for the `obsidian` dsh\\n * agent preset.\\n *\\n * What it does, on every system-prompt assembly for this agent:\\n *   1. Reads the vault's durable memory files (`.deepseek/memory/*` and a\\n *      one-line digest of `.deepseek/inbox/*`). These are maintained BY THE\\n *      MODEL through the ordinary file tools, per the vault's AGENTS.md.\\n *   2. Distills a small dialogue index from this machine's past dsh session\\n *      logs (session.jsonl.zstd files under `$DSH_HOME/sessions/`) — recent user\\n *      questions plus short assistant conclusions — so a brand-new session\\n *      no longer starts from zero.\\n *   3. Appends one bounded \\\"obsidian:memory\\\" section to the assembled system\\n *      prompt.\\n *\\n * It never calls the model and never mutates any user note. The only file it\\n * writes is its own cache at `<vault>/.deepseek/cache/dialogue-index.json`.\\n *\\n * Session logs are concatenated Zstandard frames (one JSONL batch per frame).\\n * Node >= 22.5 provides zstd through node:zlib; on older runtimes the\\n * dialogue index is skipped and only vault memory files are injected.\\n */\\n\\nimport * as zlib from \\\"node:zlib\\\";\\nimport {\\n  existsSync,\\n  mkdirSync,\\n  readdirSync,\\n  readFileSync,\\n  renameSync,\\n  statSync,\\n  writeFileSync\\n} from \\\"node:fs\\\";\\nimport { dirname, isAbsolute, join, resolve } from \\\"node:path\\\";\\nimport { homedir } from \\\"node:os\\\";\\n\\nexport const name = \\\"obsidian-memory\\\";\\nexport const inject = [\\\"systemPrompt\\\"];\\n\\nconst ZSTD_MAGIC = 4247762216; // little-endian 28 B5 2F FD\\nconst MEMORY_DIR = \\\".deepseek\\\";\\nconst CACHE_DIR = join(MEMORY_DIR, \\\"cache\\\");\\nconst CACHE_FILE = join(CACHE_DIR, \\\"dialogue-index.json\\\");\\nconst LOG_SUFFIX = \\\".jsonl.zstd\\\";\\nconst MAX_LOG_FILES = 20;\\n// Layered injection budget (arXiv:2606.24775): the prompt carries navigation\\n// layers only; raw evidence lives on disk and is reached via grep/read.\\nconst MAX_PROFILE_CHARS = 4000;\\nconst MAX_TOPIC_INDEX_CHARS = 4000;\\nconst MAX_EPISODE_INDEX_CHARS = 2500;\\nconst MAX_INBOX_CHARS = 2200;\\nconst MAX_DIALOGUE_PAIRS = 6;\\nconst MAX_DIALOGUE_CHARS = 3000;\\nconst DEFAULT_MAX_HISTORY_ENTRIES = 40;\\nconst DEFAULT_MAX_HISTORY_CHARS = 6000;\\n\\n// ── zstd session-log decoding ───────────────────────────────────────────────\\n\\n/** Locate every complete Zstandard frame in a concatenated-frame file. */\\nexport function scanZstdFrames(buffer) {\\n  const frames = [];\\n  let offset = 0;\\n  while (offset < buffer.length) {\\n    const start = offset;\\n    if (buffer.length - offset < 4) return frames;\\n    if (buffer.readUInt32LE(offset) !== ZSTD_MAGIC) {\\n      throw new Error(`obsidian-memory: bad zstd frame magic at byte ${offset}`);\\n    }\\n    offset += 4;\\n    const descriptor = buffer.readUInt8(offset);\\n    offset += 1;\\n    const contentSizeFlag = descriptor >>> 6;\\n    const singleSegment = (descriptor & 32) !== 0;\\n    const hasChecksum = (descriptor & 4) !== 0;\\n    const dictionaryFlag = descriptor & 3;\\n    const dictionaryBytes = dictionaryFlag === 3 ? 4 : dictionaryFlag;\\n    const contentSizeBytes = contentSizeFlag === 0 ? (singleSegment ? 1 : 0) : (1 << contentSizeFlag);\\n    offset += (singleSegment ? 0 : 1) + dictionaryBytes + contentSizeBytes;\\n    for (;;) {\\n      const blockHeader = buffer.readUIntLE(offset, 3);\\n      offset += 3;\\n      const lastBlock = (blockHeader & 1) !== 0;\\n      const blockType = (blockHeader >>> 1) & 3;\\n      const blockSize = blockHeader >>> 3;\\n      if (blockType === 3) throw new Error(`obsidian-memory: reserved zstd block type at byte ${offset - 3}`);\\n      const payloadBytes = blockType === 1 ? 1 : blockSize;\\n      offset += payloadBytes;\\n      if (lastBlock) break;\\n    }\\n    if (hasChecksum) offset += 4;\\n    frames.push([start, offset]);\\n  }\\n  return frames;\\n}\\n\\n/** Decode one full session artifact into its JSONL event objects. */\\nexport function decodeZstdSessionLog(buffer) {\\n  const events = [];\\n  if (typeof zlib.zstdDecompressSync !== \\\"function\\\") return events;\\n  for (const [start, end] of scanZstdFrames(buffer)) {\\n    let text;\\n    try {\\n      text = zlib.zstdDecompressSync(buffer.subarray(start, end)).toString(\\\"utf8\\\");\\n    } catch {\\n      continue; // tolerate a torn/foreign final frame; keep committed frames\\n    }\\n    for (const line of text.split(\\\"\\\\n\\\")) {\\n      if (line.trim() === \\\"\\\") continue;\\n      try {\\n        events.push(JSON.parse(line));\\n      } catch {\\n        // Ignore malformed individual lines; the durable log is append-only.\\n      }\\n    }\\n  }\\n  return events;\\n}\\n\\n// ── text extraction ─────────────────────────────────────────────────────────\\n\\nfunction contentText(content) {\\n  if (!Array.isArray(content)) return \\\"\\\";\\n  return content\\n    .filter((block) => block?.type === \\\"text\\\" && typeof block.text === \\\"string\\\")\\n    .map((block) => block.text)\\n    .join(\\\"\\\\n\\\")\\n    .trim();\\n}\\n\\nfunction clip(text, maxChars) {\\n  if (text.length <= maxChars) return text;\\n  return `${text.slice(0, maxChars).replace(/\\\\s+\\\\S*$/, \\\"\\\")} …`;\\n}\\n\\n/**\\n * Walk one decoded session into a compact entry:\\n * `{ id, title, cwd, messages: [{ role, text, time }] }`.\\n * Plugin-injected user messages (runtime-context snapshots, approval notices)\\n * are skipped; only real human turns (`source.kind === \\\"user\\\"`) count.\\n */\\nexport function distillSession(events) {\\n  const entry = { id: undefined, title: undefined, cwd: undefined, messages: [] };\\n  for (const event of events) {\\n    if (event?.type === \\\"session\\\" && typeof event.id === \\\"string\\\") {\\n      entry.id = event.id;\\n      entry.cwd = typeof event.cwd === \\\"string\\\" ? event.cwd : entry.cwd;\\n    } else if (event?.type === \\\"session/title\\\" && typeof event.data?.title === \\\"string\\\") {\\n      entry.title = event.data.title;\\n    } else if (event?.type === \\\"user/message\\\" && event.data?.source?.kind === \\\"user\\\") {\\n      const text = contentText(event.data.content);\\n      if (text !== \\\"\\\") {\\n        entry.messages.push({ role: \\\"user\\\", text: clip(text, 500), time: event.time ?? 0 });\\n      }\\n    } else if (event?.type === \\\"assistant/message\\\") {\\n      const text = contentText(event.data?.message?.content);\\n      if (text !== \\\"\\\") {\\n        entry.messages.push({ role: \\\"assistant\\\", text: clip(text, 320), time: event.time ?? 0 });\\n      }\\n    }\\n  }\\n  return entry;\\n}\\n\\n// ── session root walking ────────────────────────────────────────────────────\\n\\n/** Recursively list session artifacts, newest first, bounded by `maxFiles`. */\\nexport function findSessionLogs(sessionsRoot, maxFiles = MAX_LOG_FILES) {\\n  const found = [];\\n  const walk = (dir) => {\\n    let children;\\n    try {\\n      children = readdirSync(dir, { withFileTypes: true });\\n    } catch {\\n      return;\\n    }\\n    for (const child of children) {\\n      const path = join(dir, child.name);\\n      if (child.isDirectory()) walk(path);\\n      else if (child.isFile() && child.name.endsWith(LOG_SUFFIX)) {\\n        try {\\n          const stats = statSync(path);\\n          found.push({ path, mtimeMs: stats.mtimeMs, size: stats.size });\\n        } catch {\\n          // Gone while walking; skip.\\n        }\\n      }\\n    }\\n  };\\n  walk(sessionsRoot);\\n  found.sort((a, b) => b.mtimeMs - a.mtimeMs);\\n  return found.slice(0, maxFiles);\\n}\\n\\n/**\\n * Build the dialogue index used by the memory section: recent user turns and\\n * the assistant texts that followed, flattened in time order.\\n */\\nexport function buildDialogueIndex(sessionsRoot, maxEntries, maxChars, maxFiles = MAX_LOG_FILES) {\\n  const sources = [];\\n  const sessions = [];\\n  for (const log of findSessionLogs(sessionsRoot, maxFiles)) {\\n    let buffer;\\n    try {\\n      buffer = readFileSync(log.path);\\n    } catch {\\n      continue;\\n    }\\n    let events = [];\\n    try {\\n      events = decodeZstdSessionLog(buffer);\\n    } catch {\\n      continue;\\n    }\\n    const entry = distillSession(events);\\n    if (entry.id !== undefined && entry.messages.length > 0) {\\n      sources.push({ path: log.path, mtimeMs: log.mtimeMs, size: log.size });\\n      sessions.push(entry);\\n    }\\n  }\\n\\n  // Turn each real user message into a Q/A pair: the question plus the first\\n  // assistant text that followed it in the same session. Newest pairs first.\\n  const threads = [];\\n  for (const session of sessions) {\\n    const messages = [...session.messages].sort((a, b) => a.time - b.time);\\n    for (let index = 0; index < messages.length; index += 1) {\\n      const message = messages[index];\\n      if (message.role !== \\\"user\\\") continue;\\n      const answer = messages.slice(index + 1).find((candidate) => candidate.role === \\\"assistant\\\");\\n      threads.push({\\n        sessionId: session.id,\\n        title: session.title,\\n        cwd: session.cwd,\\n        time: message.time,\\n        user: message,\\n        assistant: answer\\n      });\\n    }\\n  }\\n  threads.sort((a, b) => a.time - b.time);\\n\\n  const entries = [];\\n  let used = 0;\\n  for (const thread of threads.slice(-maxEntries).reverse()) {\\n    const question = thread.user.text;\\n    const answer = thread.assistant?.text ?? \\\"\\\";\\n    const questionBudget = Math.min(question.length, 400);\\n    const answerBudget = Math.min(answer.length, 240);\\n    if (used + questionBudget + answerBudget > maxChars) break;\\n    entries.push({\\n      sessionId: thread.sessionId,\\n      title: typeof thread.title === \\\"string\\\" ? thread.title : undefined,\\n      role: \\\"user\\\",\\n      text: question.slice(0, questionBudget),\\n      time: thread.time\\n    });\\n    used += questionBudget;\\n    if (answerBudget > 0) {\\n      entries.push({\\n        sessionId: thread.sessionId,\\n        title: typeof thread.title === \\\"string\\\" ? thread.title : undefined,\\n        role: \\\"assistant\\\",\\n        text: answer.slice(0, answerBudget),\\n        time: thread.time\\n      });\\n      used += answerBudget;\\n    }\\n  }\\n  return {\\n    generatedAt: Date.now(),\\n    sources,\\n    entries\\n  };\\n}\\n\\n// ── durable vault memory files ──────────────────────────────────────────────\\n\\nfunction readMemoryFile(root, relativePath, maxChars) {\\n  const path = join(root, relativePath);\\n  if (!existsSync(path)) return \\\"\\\";\\n  try {\\n    return clip(readFileSync(path, \\\"utf8\\\").trim(), maxChars);\\n  } catch {\\n    return \\\"\\\";\\n  }\\n}\\n\\n/** Files that are memo-library scaffolding, not memos. */\\nconst MEMO_SCAFFOLD = new Set([\\\"index.md\\\", \\\"_README.md\\\"]);\\nconst MEMO_STATES = new Set([\\\"inbox\\\", \\\"polishing\\\", \\\"done\\\"]);\\nconst MEMO_STALE_INBOX_DAYS = 7;\\nconst MEMO_STALE_POLISHING_DAYS = 3;\\n\\n/** Parse the YAML-ish frontmatter of one memo plus its first `#` title. */\\nexport function parseMemoFrontmatter(text) {\\n  const meta = {};\\n  const match = /^---\\\\r?\\\\n([\\\\s\\\\S]*?)\\\\r?\\\\n---/.exec(text ?? \\\"\\\");\\n  if (match !== null) {\\n    for (const line of match[1].split(/\\\\r?\\\\n/)) {\\n      const pair = /^([A-Za-z_][\\\\w-]*):\\\\s*(.*)$/.exec(line.trim());\\n      if (pair !== null) meta[pair[1]] = pair[2].trim().replace(/^[\\\"']|[\\\"']$/g, \\\"\\\");\\n    }\\n  }\\n  const title = /^#\\\\s+(.+)$/m.exec(text ?? \\\"\\\")?.[1]?.trim();\\n  if (title !== undefined && meta.title === undefined) meta.title = title;\\n  return meta;\\n}\\n\\nfunction parseLocalDay(value) {\\n  const match = /^(\\\\d{4})-(\\\\d{2})-(\\\\d{2})/.exec(value ?? \\\"\\\");\\n  if (match === null) return null;\\n  return new Date(Number(match[1]), Number(match[2]) - 1, Number(match[3]));\\n}\\n\\nfunction daysSinceLocal(value) {\\n  const day = parseLocalDay(value);\\n  if (day === null) return null;\\n  return Math.floor((Date.now() - day.getTime()) / 86400000);\\n}\\n\\nfunction localDateString() {\\n  const now = new Date();\\n  return `${now.getFullYear()}-${String(now.getMonth() + 1).padStart(2, \\\"0\\\")}-${String(now.getDate()).padStart(2, \\\"0\\\")}`;\\n}\\n\\n/**\\n * Memo status digest: group live memos by lifecycle state and surface the\\n * top stale candidates (inbox >= 7 days, polishing >= 3 days, and not yet\\n * reminded today) for the agent's proactive review prompts.\\n */\\nexport function memoDigest(root, maxChars) {\\n  const memoDir = join(root, MEMORY_DIR, \\\"inbox\\\");\\n  if (!existsSync(memoDir)) return \\\"\\\";\\n  let files = [];\\n  try {\\n    files = readdirSync(memoDir, { withFileTypes: true })\\n      .filter((entry) => entry.isFile() && entry.name.endsWith(\\\".md\\\") && !MEMO_SCAFFOLD.has(entry.name) && !entry.name.startsWith(\\\"_\\\"))\\n      .map((entry) => entry.name);\\n  } catch {\\n    return \\\"\\\";\\n  }\\n  if (files.length === 0) return \\\"\\\";\\n\\n  const groups = { inbox: [], polishing: [], done: [] };\\n  const today = localDateString();\\n  for (const file of files) {\\n    let meta;\\n    try {\\n      meta = parseMemoFrontmatter(readFileSync(join(memoDir, file), \\\"utf8\\\"));\\n    } catch {\\n      continue;\\n    }\\n    const slug = file.replace(/\\\\.md$/, \\\"\\\");\\n    const status = MEMO_STATES.has(meta.status) ? meta.status : \\\"inbox\\\";\\n    const updated = meta.updated ?? \\\"\\\";\\n    const days = daysSinceLocal(updated);\\n    const item = {\\n      slug,\\n      title: meta.title || slug,\\n      topic: meta.topic || \\\"未归类\\\",\\n      updated,\\n      days,\\n      stale: days !== null && days >= (status === \\\"polishing\\\" ? MEMO_STALE_POLISHING_DAYS : MEMO_STALE_INBOX_DAYS),\\n      alreadyReminded: meta.last_reminded === today\\n    };\\n    groups[status].push(item);\\n  }\\n\\n  const stateLabel = { inbox: \\\"待打磨\\\", polishing: \\\"打磨中\\\", done: \\\"已完成\\\" };\\n  const lines = [];\\n  for (const status of [\\\"inbox\\\", \\\"polishing\\\", \\\"done\\\"]) {\\n    const members = groups[status].sort((a, b) => (b.days ?? -1) - (a.days ?? -1));\\n    if (members.length === 0) continue;\\n    lines.push(`- ${stateLabel[status]}（${status}）· ${members.length} 条`);\\n    for (const memo of members) {\\n      const parts = [`[[${memo.slug}|${memo.title}]]`, `主题:${memo.topic}`];\\n      if (memo.updated !== \\\"\\\") parts.push(`updated:${memo.updated}`);\\n      lines.push(`  - ${parts.join(\\\" · \\\")}`);\\n    }\\n  }\\n\\n  const candidates = [...groups.inbox, ...groups.polishing]\\n    .filter((memo) => memo.stale && !memo.alreadyReminded)\\n    .sort((a, b) => (b.days ?? -1) - (a.days ?? -1))\\n    .slice(0, 3);\\n  if (candidates.length > 0) {\\n    lines.push(\\\"- 🔔 提醒候选（久未更新）\\\");\\n    for (const memo of candidates) {\\n      lines.push(`  - [[${memo.slug}|${memo.title}]]：${memo.days} 天未更新，可在相关讨论时建议打磨`);\\n    }\\n  }\\n\\n  return clip(lines.join(\\\"\\\\n\\\"), maxChars);\\n}\\n\\n/** Episode timeline: keep the newest lines (list items only) within budget. */\\nfunction episodeIndexDigest(root, maxChars) {\\n  const path = join(root, MEMORY_DIR, \\\"memory\\\", \\\"episodes\\\", \\\"index.md\\\");\\n  if (!existsSync(path)) return \\\"\\\";\\n  try {\\n    const text = readFileSync(path, \\\"utf8\\\").trim();\\n    if (text === \\\"\\\") return \\\"\\\";\\n    const items = text.split(\\\"\\\\n\\\").filter((line) => line.trim().startsWith(\\\"-\\\"));\\n    if (items.length === 0) return clip(text, maxChars);\\n    // Index lines are append-only, newest at the bottom: keep the tail.\\n    const kept = [];\\n    let used = 0;\\n    for (const line of items.reverse()) {\\n      const clean = clip(line.trim(), maxChars);\\n      if (used + clean.length > maxChars) break;\\n      kept.push(clean);\\n      used += clean.length + 1;\\n    }\\n    return kept.reverse().join(\\\"\\\\n\\\");\\n  } catch {\\n    return \\\"\\\";\\n  }\\n}\\n\\n// ── the section composer ────────────────────────────────────────────────────\\n\\n/**\\n * Render the layered memory section for one agent.\\n *\\n * Layout follows the paper's routing philosophy: stable semantics + topic\\n * navigation + inbox/episode timelines are always injected (coarse layers);\\n * raw episodic evidence is left on disk for grep/read (fine layer). Past\\n * dialogue cues are capped at a few Q/A pairs to keep the prompt bounded.\\n * `context.agent` supplies the current session id so the live conversation is\\n * never duplicated into the \\\"past dialogue\\\" index.\\n */\\nexport function buildMemorySection({ vaultRoot, sessionsRoot, maxHistoryEntries, maxHistoryChars, cacheTtlMs }, currentSessionId, dialogueIndex) {\\n  const profile = readMemoryFile(vaultRoot, join(MEMORY_DIR, \\\"memory\\\", \\\"profile.md\\\"), MAX_PROFILE_CHARS);\\n  const topics = readMemoryFile(vaultRoot, join(MEMORY_DIR, \\\"memory\\\", \\\"topics\\\", \\\"index.md\\\"), MAX_TOPIC_INDEX_CHARS);\\n  const episodes = episodeIndexDigest(vaultRoot, MAX_EPISODE_INDEX_CHARS);\\n  const memos = memoDigest(vaultRoot, MAX_INBOX_CHARS);\\n\\n  const lines = [\\n    \\\"## 分层长期记忆（由 obsidian-memory 自动注入；导航层在此，证据层在磁盘）\\\",\\n    \\\"\\\",\\n    \\\"记忆按 arXiv:2606.24775 的四模块原则组织：profile=语义层，topics=导航层，\\\" +\\n    \\\"episodes=原始证据层，inbox=想法层。以下内容用于“知道去哪找”，不要当作完整证据。\\\" +\\n    \\\"回答细节问题时必须按路由规则读文件：\\\",\\n    \\\"- 精确事实 / 用户原话 / 日期数字 → 先 grep `.deepseek/memory/episodes/` 再读命中文件；\\\",\\n    \\\"- 主题来龙去脉 → 先读 `.deepseek/memory/topics/index.md` 定位，再读 `topics/<slug>.md` 或相关笔记；\\\",\\n    \\\"- “当前最新状态” → 比较 frontmatter `updated` 或最新 episode 时间戳；\\\",\\n    \\\"- 检索不到就明说没有，不要编造。\\\"\\n  ];\\n\\n  if (profile !== \\\"\\\") {\\n    lines.push(\\\"\\\", \\\"### 用户画像与稳定偏好（.deepseek/memory/profile.md）\\\", \\\"\\\", profile);\\n  } else {\\n    lines.push(\\\"\\\", \\\"### 用户画像与稳定偏好\\\", \\\"\\\", \\\"（尚未建立。按 AGENTS.md 在首次对话后创建 .deepseek/memory/profile.md。）\\\");\\n  }\\n\\n  if (topics !== \\\"\\\") {\\n    lines.push(\\\"\\\", \\\"### 研究主题索引（.deepseek/memory/topics/index.md）\\\", \\\"\\\", topics);\\n  } else {\\n    lines.push(\\\"\\\", \\\"### 研究主题索引\\\", \\\"\\\", \\\"（尚未建立。按 AGENTS.md 在 .deepseek/memory/topics/index.md 维护主题条目。）\\\");\\n  }\\n\\n  if (episodes !== \\\"\\\") {\\n    lines.push(\\\"\\\", \\\"### 近期事件时间线（.deepseek/memory/episodes/index.md，最新在前）\\\", \\\"\\\", episodes);\\n  } else {\\n    lines.push(\\\"\\\", \\\"### 近期事件时间线\\\", \\\"\\\", \\\"（尚无事件记录。每轮对话收尾时按 AGENTS.md 双写 episodes。）\\\");\\n  }\\n\\n  if (memos !== \\\"\\\") {\\n    lines.push(\\\"\\\", \\\"### 备忘录状态与提醒候选（.deepseek/inbox/，AI 维护）\\\", \\\"\\\", memos,\\n      \\\"\\\", \\\"当本轮讨论与上述某条 memo 明显相关（新证据、新反例、可推进其“待打磨”清单）时，\\\",\\n      \\\"按 AGENTS.md 第 5 节在回复末尾给出“🔔 备忘录提醒”并用 ask_user_question 询问是否现在打磨；\\\",\\n      \\\"每条 memo 每天最多提醒一次，提醒后把它的 last_reminded 更新为当天日期。\\\");\\n  } else {\\n    lines.push(\\\"\\\", \\\"### 备忘录状态与提醒候选\\\", \\\"\\\", \\\"（.deepseek/inbox/ 尚无 memo。捕捉到新想法并经用户同意后，按 AGENTS.md 第 5 节创建。）\\\");\\n  }\\n\\n  // Past-dialogue cues: newest first, at most MAX_DIALOGUE_PAIRS Q/A pairs.\\n  const recent = (dialogueIndex?.entries ?? []).filter((entry) => entry.sessionId !== currentSessionId);\\n  if (recent.length > 0) {\\n    const cues = [];\\n    let pairs = 0;\\n    let used = 0;\\n    for (const entry of recent) {\\n      const text = entry.text.replace(/\\\\n+/g, \\\" \\\");\\n      const budget = entry.role === \\\"user\\\" ? Math.min(text.length, 320) : Math.min(text.length, 220);\\n      if (used + budget > MAX_DIALOGUE_CHARS) break;\\n      if (entry.role === \\\"user\\\") {\\n        if (pairs >= MAX_DIALOGUE_PAIRS) break;\\n        pairs += 1;\\n      } else if (pairs === 0) {\\n        continue; // never start with an orphaned assistant cue\\n      }\\n      cues.push({ ...entry, text: text.slice(0, budget) });\\n      used += budget;\\n    }\\n    if (cues.length > 0) {\\n      lines.push(\\\"\\\", \\\"### 近期跨会话问答线索（最多 6 组，细节请 grep episodes）\\\", \\\"\\\");\\n      let lastSessionId;\\n      for (const entry of cues) {\\n        if (entry.sessionId !== lastSessionId) {\\n          lines.push(`- 会话${entry.title !== undefined ? `《${entry.title}》` : \\\"\\\"}（${new Date(entry.time).toLocaleString(\\\"zh-CN\\\", { hour12: false })}）`);\\n          lastSessionId = entry.sessionId;\\n        }\\n        const label = entry.role === \\\"user\\\" ? \\\"问\\\" : \\\"答\\\";\\n        lines.push(`  - ${label}: ${entry.text}`);\\n      }\\n    }\\n  }\\n\\n  return lines.join(\\\"\\\\n\\\");\\n}\\n\\n// ── engine with per-process caching ─────────────────────────────────────────\\n\\nfunction defaultSessionsRoot() {\\n  const home = process.env.DSH_HOME ?? join(homedir(), \\\".dsh\\\");\\n  return join(home, \\\"sessions\\\");\\n}\\n\\nfunction normalizeConfig(config) {\\n  const vaultRaw = (process.env.DSH_OBSIDIAN_VAULT ?? config.vaultRoot ?? \\\"\\\").trim();\\n  // Empty vaultRoot means \\\"the agent's session cwd\\\" — resolved per agent so the\\n  // same preset is portable across machines and vaults.\\n  const vaultRoot = vaultRaw === \\\"\\\" ? \\\"\\\" : resolve(vaultRaw);\\n  const sessionsRaw = (process.env.DSH_SESSIONS_ROOT ?? config.sessionsRoot ?? \\\"\\\").trim();\\n  const sessionsRoot = resolve(sessionsRaw === \\\"\\\" ? defaultSessionsRoot() : sessionsRaw);\\n  const maxHistoryEntries = Number.isInteger(config.maxHistoryEntries) && config.maxHistoryEntries > 0\\n    ? config.maxHistoryEntries\\n    : DEFAULT_MAX_HISTORY_ENTRIES;\\n  const maxHistoryChars = Number.isInteger(config.maxHistoryChars) && config.maxHistoryChars > 0\\n    ? config.maxHistoryChars\\n    : DEFAULT_MAX_HISTORY_CHARS;\\n  const cacheTtlMs = Number.isFinite(config.cacheTtlMs) && config.cacheTtlMs >= 0 ? config.cacheTtlMs : 0;\\n  if (!isAbsolute(sessionsRoot)) throw new TypeError(\\\"obsidian-memory: sessionsRoot must be an absolute path\\\");\\n  return { vaultRoot, sessionsRoot, maxHistoryEntries, maxHistoryChars, cacheTtlMs };\\n}\\n\\nfunction resolveVaultRoot(config, agent) {\\n  if (config.vaultRoot !== \\\"\\\") return config.vaultRoot;\\n  const cwd = agent?.session?.header?.cwd ?? agent?.session?.cwd;\\n  if (typeof cwd === \\\"string\\\" && cwd !== \\\"\\\" && isAbsolute(cwd)) return cwd;\\n  return \\\"\\\";\\n}\\n\\nfunction fingerprint(logs) {\\n  return logs.map((log) => `${log.path}|${log.mtimeMs}|${log.size}`).join(\\\"\\\\n\\\");\\n}\\n\\nfunction readCachedIndex(cachePath) {\\n  try {\\n    const cached = JSON.parse(readFileSync(cachePath, \\\"utf8\\\"));\\n    if (Array.isArray(cached?.entries) && Array.isArray(cached?.sources)) return cached;\\n  } catch {\\n    // Cache missing/corrupt: rebuild.\\n  }\\n  return undefined;\\n}\\n\\nfunction writeCachedIndex(cachePath, index) {\\n  try {\\n    mkdirSync(dirname(cachePath), { recursive: true });\\n    const staging = `${cachePath}.tmp-${process.pid}`;\\n    writeFileSync(staging, JSON.stringify(index));\\n    renameSync(staging, cachePath);\\n  } catch {\\n    // A cache write failure must never break the prompt.\\n  }\\n}\\n\\nclass MemoryEngine {\\n  #config;\\n  #cachedIndex;\\n  #fingerprint = \\\"\\\";\\n  #builtAt = 0;\\n\\n  constructor(config) {\\n    this.#config = normalizeConfig(config);\\n  }\\n\\n  cachePathFor(vaultRoot) {\\n    return join(vaultRoot, CACHE_FILE);\\n  }\\n\\n  /** Return the current dialogue index, rebuilding it only when sources changed. */\\n  getDialogueIndex(vaultRoot, force = false) {\\n    const config = this.#config;\\n    const logs = findSessionLogs(config.sessionsRoot, MAX_LOG_FILES);\\n    const current = fingerprint(logs);\\n    const stale = force ||\\n      this.#cachedIndex === undefined ||\\n      current !== this.#fingerprint ||\\n      (config.cacheTtlMs > 0 && Date.now() - this.#builtAt > config.cacheTtlMs);\\n    if (!stale) return this.#cachedIndex;\\n\\n    // Reuse the on-disk cache when its source fingerprint still matches.\\n    if (this.#cachedIndex === undefined) {\\n      const disk = readCachedIndex(this.cachePathFor(vaultRoot));\\n      if (disk !== undefined && fingerprint(disk.sources ?? []) === current) {\\n        this.#cachedIndex = disk;\\n        this.#fingerprint = current;\\n        this.#builtAt = disk.generatedAt ?? Date.now();\\n        return this.#cachedIndex;\\n      }\\n    }\\n\\n    const index = buildDialogueIndex(\\n      config.sessionsRoot,\\n      config.maxHistoryEntries,\\n      config.maxHistoryChars,\\n      MAX_LOG_FILES\\n    );\\n    this.#cachedIndex = index;\\n    this.#fingerprint = current;\\n    this.#builtAt = Date.now();\\n    writeCachedIndex(this.cachePathFor(vaultRoot), index);\\n    return index;\\n  }\\n\\n  async sectionForAgent(agent) {\\n    const config = this.#config;\\n    try {\\n      const vaultRoot = resolveVaultRoot(config, agent);\\n      if (vaultRoot === \\\"\\\") {\\n        return \\\"## 长期记忆（obsidian-memory 未配置）\\\\n\\\\n\\\" +\\n          \\\"当前会话没有可用的 vault 工作目录；设置 DSH_OBSIDIAN_VAULT 或在 preset 配置 vaultRoot。\\\";\\n      }\\n      const currentSessionId = agent?.session?.id;\\n      const dialogueIndex = this.getDialogueIndex(vaultRoot);\\n      return buildMemorySection({ ...config, vaultRoot }, currentSessionId, dialogueIndex);\\n    } catch (error) {\\n      return `## 长期记忆（obsidian-memory 暂不可用）\\\\n\\\\n${String(error)}`;\\n    }\\n  }\\n}\\n\\n// ── Cordis plugin entry ─────────────────────────────────────────────────────\\n\\nexport function apply(ctx, config) {\\n  const engine = new MemoryEngine(config);\\n  ctx.on(\\\"system-prompt/assemble\\\", async (assembly, context, next) => {\\n    const assembled = await next();\\n    if (context?.agent === undefined) return assembled;\\n    const text = await engine.sectionForAgent(context.agent);\\n    if (text === \\\"\\\") return assembled;\\n    return {\\n      ...assembled,\\n      sections: [...assembled.sections, { name: \\\"obsidian:memory\\\", text }]\\n    };\\n  });\\n}\\n\",\"profile-package.json\":\"{\\n  \\\"name\\\": \\\"dsh-profile-obsidian\\\",\\n  \\\"private\\\": true,\\n  \\\"dependencies\\\": {},\\n  \\\"dsh\\\": {\\n    \\\"profile\\\": {\\n      \\\"bundles\\\": [\\n        \\\"@deepseek-ai/dsh-base\\\",\\n        \\\"@deepseek-ai/dsh-web-app\\\"\\n      ]\\n    }\\n  }\\n}\\n\",\"profile-cordis.yml\":\"# dsh profile root — an empty entry list. The tree is composed as patches:\\n# each bundle in package.json's dsh.profile.bundles, then cordis.patch.yml, then any\\n# --patch overlays. Edit cordis.patch.yml, not this file.\\n[]\\n\",\"profile-cordis.patch.yml\":\"# Obsidian mode patch layer, applied after dsh-base + dsh-web-app.\\n#\\n# A patch replaces the targeted row's whole config, so each row below\\n# restates the keys it owns.\\n\\n# The agent this profile defaults to: only file read/write/search + ask_user,\\n# plus the cross-session memory plugin.\\n- id: agent-presets\\n  config:\\n    default: obsidian\\n    includeUserRoot: true\\n\\n# Confine every model write to the Obsidian vault (reads stay unrestricted,\\n# matching the harness read model). Set DSH_OBSIDIAN_VAULT to override the\\n# machine-local default without editing this file.\\n- id: sandbox-policy\\n  config:\\n    mode: workspace-write\\n    workspaceRoot: !!js process.env.DSH_OBSIDIAN_VAULT ?? process.cwd()\\n\\n# Default relative-path root for the filesystem backend.\\n- id: fs-sandbox\\n  config:\\n    cwd: !!js process.env.DSH_OBSIDIAN_VAULT ?? process.cwd()\\n\",\"profile-pnpm-workspace.yaml\":\"packages:\\n  - .\\n\\nnodeLinker: hoisted\\nautoInstallPeers: false\\n\"}");
const EMBEDDED_TEMPLATES = JSON.parse("{\"AGENTS.md\":\"# DeepSeek 笔记助手 · 工作协议（AGENTS.md）\\n\\n> 记忆协议依据 arXiv:2606.24775《Are We Ready For An Agent-Native Memory System?》的四模块框架设计：表示与存储、提取、检索与路由、维护。核心原则：**原文证据优先于摘要、写时保留而非早过滤、检索先粗后细、维护只做局部更新。**\\n\\n你是本 vault 的长期笔记助手。下面的协议每轮对话都生效；具体优先级：直接用户指令 > 本文件 > 记忆文件。\\n\\n## 0. 硬约束\\n\\n- 你只有文件读写/搜索工具和 ask_user 提问工具。所有读写都限定在本 vault 内。\\n- 先读再答，禁止臆造用户笔记里的内容、记号或结论。不确定就 grep/read 或问。\\n- 保留用户既有的记号、术语、写作风格；修改笔记用最小 diff，不要重排或“润色”成你自己的文风。\\n- 用户是数学背景，笔记可能涉及数学、统计学、经济学、R 语言、LaTeX。\\n\\n## 1. 会话开始协议（每次新会话自动执行）\\n\\n1. 系统提示中已由插件自动注入：`profile.md`（画像）、`topics/index.md`（主题导航）、`inbox/` 清单、`episodes/index.md` 近期事件索引、最近 6 组跨会话问答线索。\\n2. 按下面第 4 节的**检索路由规则**按需补读完整文件；不要只凭注入的摘要回答细节问题。\\n3. 回答前先定位并读取相关笔记；找不到就用搜索，不要重复问用户“你以前说过什么”。\\n\\n## 2. 记忆维护协议（解决“问了又忘、忘了又问”）\\n\\n### 2.1 分层表示（论文 M1：证据保真 > 抽象度）\\n\\n| 层 | 文件 | 内容 | 规则 |\\n|---|---|---|---|\\n| 语义层 | `memory/profile.md` | 稳定偏好、记号、长期授权、**当前有效事实** | 短，只放“现在成立”的结论 |\\n| 导航层 | `memory/topics/index.md` + `topics/<slug>.md` | 主题概览与主题细节 | 索引只做路由，细节进主题文件 |\\n| 证据层 | `memory/episodes/YYYY-MM-DD-<slug>.md` | 每轮对话的原始事件卡片 | **append-only，不删除、不重写历史** |\\n| 想法层 | `inbox/` | 待打磨想法 | 经同意写入 |\\n\\n### 2.2 写时提取（论文 M2：晚过滤原则）\\n\\n每轮收尾前执行**双写**，顺序固定，不要拖到会话结束：\\n\\n1. **先写证据层**：向 `episodes/YYYY-MM-DD-<slug>.md` 追加一个事件节（同一天追加到当天文件，新一天开新文件）：\\n   ```markdown\\n   ## HH:MM <一句话标题>\\n   - 用户原话/关键表述：<保留原句，宁多勿删>\\n   - 结论/产出：<本轮的实质结论，保留关键细节与数字>\\n   - 事实修正：<如有，写“旧事实 → 新事实”，保留旧值>\\n   - 涉及：[[笔记]] · 主题：<topic> · 想法：<inbox 条目，如有>\\n   ```\\n2. **再局部更新语义/导航层**：\\n   - 稳定偏好、记号、授权 → `profile.md` 对应小节（合并同类项，更新而非无限追加；每改一条事实，在文件末尾“修订历史”加一行）。\\n   - 新主题/结论/重要文件 → `topics/index.md` 增改条目；细节超过 3 行则放 `topics/<slug>.md`，索引里留链接。\\n   - **禁止**把整段对话总结进 profile/topics；原文只放 episodes。\\n3. **版本化更正**：同一事实被推翻时，在新 episode 写更正；profile/topics 中旧值改为“~~旧值~~ → 新值（YYYY-MM-DD）”，不要抹掉旧值。\\n4. 写完后更新 `episodes/index.md`：`- [[YYYY-MM-DD-slug|标题]] — 主题A、主题B`（只加一行）。\\n\\n### 2.3 局部维护（论文 M5：维护范围决定成本）\\n\\n- 每次只改动相关小节/条目；**不要**为了“整理”重写整个记忆文件。\\n- 保守合并：只有明确冗余（同一事实两个条目）才合并；合并时保留最早时间戳。\\n- 归档：`episodes/` 超过约 40 个文件时，把最旧的移动到 `memory/episodes/archive/`（原样移动，不摘要、不合并），并在 index 中改链接；其他文件不动作业。\\n- `profile.md` 超过约 120 行时：把“当前关注”里已收束的条目下沉为 episodes 引用，不在 profile 里长存过程性内容。\\n\\n## 3. 笔记工作流（写作、梳理、补全、审阅、找问题）\\n\\n用户最常见的求助，按场景处理：\\n\\n1. **帮我理清思路**：先复述笔记当前结构，指出主线的断点与重复，给出 2-3 个候选重组方案（含理由），让用户选，不要直接大改。\\n2. **帮我完善细节**：补证明步骤、展开例子、补定义；补写的内容标注 `<!-- AI 补全 -->`，让用户可回看。\\n3. **审阅当前笔记**：按“数学/逻辑错误 > 结构问题 > 表述与记号 > 小瑕疵”分级列出，先讲最严重的；给出具体修改建议但默认不直接改。\\n4. **找笔记里的问题**：主动检查：假设是否明示、定义是否先于使用、记号是否前后一致、例子是否与定理匹配、引用是否断裂（Obsidian 链接）。\\n5. 修改前先说明改动计划；大改或删内容前用 ask_user 确认。\\n\\n## 4. 记忆检索路由（论文 M3：先规划、粗到细、混合检索）\\n\\n回答涉及“以前说过/做过什么”时，先花一步做检索规划，再按类型取证据：\\n\\n| 查询类型 | 路由 |\\n|---|---|\\n| 精确事实、用户原话、日期、数字 | `grep` 检索 `.deepseek/memory/episodes/`，命中后读对应 episode |\\n| 稳定偏好 / 记号 / 授权 | 读 `memory/profile.md`（细查用 grep） |\\n| 某个主题的来龙去脉 | 先读 `topics/index.md` 定位条目 → 再读 `topics/<slug>.md` 或相关笔记 |\\n| “当前最新状态” | 看目标文件的 `updated`/最新 episode 时间戳，优先最新 |\\n| 跨会话分散证据 | 关键词 grep episodes + 按 index 时间线索汇聚，不要只靠语义猜测 |\\n| 综合问题 | 先粗（index 定位）后细（读文件），把证据按时间排好再回答 |\\n\\n原则：一次检索能确定就不做第二次；检索不到就明说“记忆里没有”，不要编造。\\n\\n## 5. 备忘录系统：捕获 → 关联 → 打磨（含主动提醒）\\n\\n**定义**：值得捕捉的“关键想法” = 一般性的数学思路、方法、技巧、观点，可迁移到别的笔记/问题，不限于当前上下文。备忘录库 = `.deepseek/inbox/`，每条一个 md，状态在 frontmatter 中流转：`inbox → polishing → done`。\\n\\n### 5.1 捕获（经同意写新 memo）\\n\\n对话或读笔记时识别到候选，先在回复末尾给：\\n\\n```markdown\\n💡 可捕捉的想法（1-3 条）\\n- **想法名**：一句话陈述。\\n- 为什么值得捕捉：……\\n- 可能关联：[[某笔记]] / 已有 memo [[slug]] / 主题条目\\n```\\n\\n然后用 `ask_user_question` 征得同意。选项至少包含：**写入新 memo / 并入已有 memo「X」/ 稍后 / 忽略**。未经同意不得新建 memo；用户说“以后默认记录”则获得长期授权（记入 profile），之后直接写并在回复中说明。\\n\\n### 5.2 关联检测（写入前必做）\\n\\n写新 memo 前先读 `.deepseek/inbox/index.md`，判断候选是否与已有 memo 高度相关：\\n\\n- **高度相关**（同一想法的延伸/证据/反例）→ 不要新建，推荐并入已有 memo：在该 memo 的“## 关联观察”追加一条（日期 + 新证据/新角度 + 来源），更新 `related` 与 `updated`；\\n- **中度相关**（不同想法但同主题）→ 新建 memo，并在双方 frontmatter 的 `related` 里互相加双链 `[[slug]]`；\\n- **独立** → 新建。\\n\\n新建 memo 模板：\\n\\n```markdown\\n---\\ntitle: <想法名>\\ntags: [想法/待打磨]\\nstatus: inbox\\ncreated: YYYY-MM-DD\\nupdated: YYYY-MM-DD\\nlast_reminded: ''\\ntopic: <对应主题或“未归类”>\\nrelated: []\\n---\\n\\n# <想法名>\\n\\n## 想法\\n<一两句话的精确陈述>\\n\\n## 为什么值得捕捉\\n<可迁移性、与已有主题的关联>\\n\\n## 关联观察\\n<每次出现相关证据/想法就追加一条：日期、新证据、新角度、来源>\\n\\n## 待打磨\\n- [ ] <要澄清/证明/泛化的点>\\n```\\n\\n写入后：更新 `inbox/index.md` 的对应状态分组；更新当天 episode；若归到某主题，同步挂到 `topics/index.md`。\\n\\n### 5.3 自动维护（无需询问的部分）\\n\\n对话中出现与某条 memo 相关的信息时，自动做：\\n\\n- 在该 memo 的“关联观察”追加证据（更新 `updated`）；\\n- 发现 memo 之间关联时，互相补 `related` 双链；\\n- 用户完成一次打磨后：`status` 按 `inbox → polishing → done` 流转，并在 index 更新分组；\\n- `done` 时把升华内容写入正式笔记前仍需问用户，写入后 memo 保留“去向”链接（`related` 加 `[[正式笔记]]`），不删除 memo 本体。\\n\\n### 5.4 主动提醒（插件已把候选注入系统提示）\\n\\n每轮开始时注意系统提示中的 **备忘录状态摘要**。满足以下任一条件时，在本轮回复末尾附一个简短区块：\\n\\n```markdown\\n🔔 备忘录提醒\\n- [[slug|标题]]：<一句话理由，例如“你刚说的 X 正好补上了它的一个缺口”>\\n```\\n\\n然后用 `ask_user_question` 询问：**现在打磨 / 稍后 / 忽略**。\\n\\n触发条件（按优先级）：\\n\\n1. 本轮讨论/新想法与某条 `inbox` 或 `polishing` memo **明显相关**（新证据、新反例、可推进其“待打磨”清单）——这是最高优先级的提醒；\\n2. 插件标出的“陈旧候选”（`inbox` 超过 7 天未更新，或 `polishing` 超过 3 天未更新）。\\n\\n提醒纪律：\\n\\n- 每条 memo 每天最多主动提醒一次；提醒后立即把该 memo 的 `last_reminded` 更新为当天日期（无论用户怎么回答）。\\n- 每轮回复最多提醒 2 条；用户正专注讨论时只提醒最相关的那条，不刷屏。\\n- 用户可在 profile 的“长期授权”里改频率（如“备忘录只在明确相关时提醒”）。\\n\\n### 5.5 打磨流程\\n\\n用户同意打磨时：\\n\\n1. 读该 memo 全文 + `related` 指向的 memo/笔记 + 相关 episodes；\\n2. 做联想、检验、泛化：补严格表述、找反例、连接已有主题；\\n3. 把进展写回 memo（新增“## 打磨记录”小节，保留每轮打磨时间与结论）；\\n4. 若已足够成熟：`status: done`，提出写入哪篇正式笔记的建议（写入前 ask_user）；\\n5. 若还不够成熟：更新“待打磨”清单，`status: polishing`，等待下次提醒。\\n\\n## 6. 目录约定\\n\\n```text\\nvault/\\n  AGENTS.md                         本协议（自动加载）\\n  .deepseek/\\n    memory/\\n      profile.md                    用户画像与稳定偏好（语义层，AI 维护）\\n      topics/\\n        index.md                    研究主题索引（导航层）\\n        <topic>.md                  主题细节（按需创建）\\n      episodes/\\n        index.md                    事件时间索引（每行一条）\\n        YYYY-MM-DD-<slug>.md        原始事件卡片（证据层，append-only）\\n        archive/                    归档（原样移动）\\n    inbox/                          备忘录库：每条一个 md，状态 inbox→polishing→done\\n      index.md                      状态分组索引（AI 维护）\\n      <slug>.md                     单条想法（含关联观察、待打磨、打磨记录）\\n    cache/                          历史会话索引缓存（机器生成，勿动）\\n```\\n\\n## 7. 回复风格\\n\\n- 中文回复；数学内容保留 LaTeX。\\n- 先给结论，再给理由；引用笔记时用 Obsidian 双链。\\n- 不要假装记得没读过的内容；如果记忆文件缺失，说明并提议初始化。\\n\",\"profile.md\":\"---\\ntype: memory/profile\\nupdated: 2026-08-15\\n---\\n\\n# 用户画像与稳定偏好\\n\\n> 本文件由 AI 维护：只放**现在仍然成立**的稳定事实（语义层）。过程性内容与原始对话证据放 `.deepseek/memory/episodes/`。更新原则：合并同类项；事实被推翻时用“~~旧值~~ → 新值（日期）”标注，不要删除历史。\\n\\n## 研究领域\\n\\n- （待填充：长期研究的数学分支/方向）\\n- （例如：实分析、概率论、……）\\n\\n## 当前关注\\n\\n- （待填充：近期在想的问题、在写的笔记；收束后下沉到 episodes 引用）\\n\\n## 理论偏好与方法偏好\\n\\n- （待填充：喜欢的框架、证明风格、构造性 vs 存在性、例子驱动的偏好……）\\n\\n## 记号与术语习惯\\n\\n- （待填充：用户常用记号、命名约定）\\n\\n## 工具与工作流\\n\\n- 笔记工具：Obsidian（vault: `D:\\\\Obsidian笔记数据库`）\\n- 数学排版：LaTeX\\n- （可补充：R / Stata / MATLAB 等）\\n\\n## 长期授权\\n\\n- （待填充：用户说“以后默认这样”的事项，例如：关键想法默认写入备忘录）\\n\\n## 修订历史\\n\\n- （AI 每次修改某条事实时在此加一行：`YYYY-MM-DD 事项：旧值 → 新值，证据见 episodes/YYYY-MM-DD-*`）\\n\",\"topics-index.md\":\"# 研究主题索引（导航层）\\n\\n> 本文件只做**路由**：每个主题一个 `##` 条目，按当前活跃度排序。细节超过 3 行就放 `topics/<slug>.md`，这里只留链接与一行概括。\\n\\n## 使用说明\\n\\n条目模板：\\n\\n```markdown\\n## <主题名>\\n\\n- 标签：#标签1 #标签2\\n- 状态：活跃 / 暂停 / 已收束\\n- 最新状态截至：YYYY-MM-DD\\n- 核心笔记：[[笔记名]]\\n- 一句话概括：……\\n- 详情：[[topics/<slug>]]（细节、开放问题、相关想法）\\n```\\n\\n（以下开始新增条目）\\n\",\"episodes-readme.md\":\"# 事件卡说明（证据层）\\n\\n> 本目录是记忆的**原始证据层**（append-only）。AI 每轮对话收尾前先在这里追加事件卡，再去更新 profile/topics。\\n>\\n> 设计依据：arXiv:2606.24775 的发现——保留原文/轻压缩优于抽象摘要（M1），写时保留优于早过滤（M2），时间戳多版本优于删除（M4）。\\n\\n## 文件与追加规则\\n\\n- 同一天的事件追加到当天文件 `YYYY-MM-DD-<slug>.md`；跨天开新文件。\\n- 同一文件内每个事件一个 `##` 小节，按时间顺序追加，**不重写已写内容**。\\n- 事实被推翻时：在新事件里写更正，旧小节保持原样。\\n\\n## 事件卡模板\\n\\n```markdown\\n## HH:MM <一句话标题>\\n\\n- 用户原话/关键表述：<保留原句，宁多勿删>\\n- 结论/产出：<本轮的实质结论，保留关键细节与数字>\\n- 事实修正：<旧事实 → 新事实；无则省略>\\n- 涉及：[[笔记名]] · 主题：<topic> · 想法：[[YYYY-MM-DD-idea-slug]]（如有）\\n```\\n\\n## 容量与归档\\n\\n- `index.md` 每行一条：`- [[YYYY-MM-DD-slug|标题]] — 主题A、主题B`。\\n- 目录超过约 40 个文件时，把最旧文件原样移入 `archive/`（不摘要、不合并），并更新 index 链接。\\n\",\"episodes-index.md\":\"# 事件时间索引\\n\\n> AI 维护：每天/每个新事件文件加一行；文件归档到 archive/ 后把链接改到 archive/。\\n> 格式：`- [[YYYY-MM-DD-slug|标题]] — 主题A、主题B`\\n\\n（尚无事件记录）\\n\",\"inbox-readme.md\":\"# 备忘录库 · inbox 说明\\n\\n> 本目录由 AI 自动维护：捕捉“一般性的数学思路、方法、技巧、观点”（新 memo 经你同意后创建），并跟踪每条想法的生命周期：\\n> `inbox`（待打磨）→ `polishing`（打磨中）→ `done`（已归入正式笔记）。\\n>\\n> - 每条想法一个 md 文件（`<slug>.md`），状态写在 frontmatter；\\n> - 总清单在 [`index.md`](index.md)，按状态分组；\\n> - AI 会在“出现新关联想法/证据”或“条目久未更新”时主动提醒你打磨。\\n\\n## 单条 memo 模板\\n\\n```markdown\\n---\\ntitle: <想法名>\\ntags: [想法/待打磨]\\nstatus: inbox            # inbox / polishing / done\\ncreated: YYYY-MM-DD\\nupdated: YYYY-MM-DD\\nlast_reminded: ''        # AI 每次提醒后写当天日期，用于每天最多提醒一次\\ntopic: <对应主题或“未归类”>\\nrelated: []              # 相关 memo/笔记双链：[[slug]]、[[笔记名]]\\n---\\n\\n# <想法名>\\n\\n## 想法\\n<一两句话的精确陈述>\\n\\n## 为什么值得捕捉\\n<可迁移性、与已有主题的关联>\\n\\n## 关联观察\\n<每次出现相关证据/想法就追加：日期、新证据、新角度、来源>\\n\\n## 待打磨\\n- [ ] <要澄清/证明/泛化的点>\\n\\n## 打磨记录\\n<打磨时追加：日期、本轮做了什么、下一步>\\n```\\n\\n## 维护规则（AI 执行）\\n\\n1. **不重复建卡**：新想法与已有 memo 高度相关时，并入其“关联观察”，而不是新建。\\n2. **双向关联**：相关 memo 之间互相在 `related` 加双链；打磨完成时在 `related` 加正式笔记链接。\\n3. **状态流转**：每次打磨后更新 `status` 与 `index.md` 分组。\\n4. **提醒记录**：每次主动提醒后更新 `last_reminded`；默认每条每天最多提醒一次。\\n5. **不删除历史**：done 的 memo 保留原文与打磨记录，作为想法的完整档案。\\n\",\"inbox-index.md\":\"# 备忘录索引（按状态分组）\\n\\n> AI 维护：新 memo 加入对应分组；状态变化时移动行。格式：`- [[slug|标题]] · 主题 · updated: YYYY-MM-DD`\\n\\n## inbox（待打磨）\\n\\n（暂无）\\n\\n## polishing（打磨中）\\n\\n（暂无）\\n\\n## done（已归入正式笔记）\\n\\n（暂无）\\n\"}");

const DEFAULT_SETTINGS = {
  port: 3180,
  dshInstallDir: '',
  dshHome: '',
  autoStart: true,
  autoInit: true,
  showRibbon: true,
  keepAliveOnUnload: false
};

// ── small helpers ───────────────────────────────────────────────────────────

function ensureFile(target, content, overwrite = false) {
  if (!overwrite && existsSync(target)) return false;
  mkdirSync(dirname(target), { recursive: true });
  writeFileSync(target, content, 'utf8');
  return true;
}

function sleep(ms) {
  return new Promise((resolve) => setTimeout(resolve, ms));
}

async function probeService(port, timeoutMs = 1500) {
  try {
    const controller = new AbortController();
    const timer = setTimeout(() => controller.abort(), timeoutMs);
    const response = await fetch(`http://127.0.0.1:${port}/`, { signal: controller.signal });
    clearTimeout(timer);
    return response.status >= 200 && response.status < 500;
  } catch {
    return false;
  }
}

/**
 * The dsh server is a Node program. `process.execPath` inside Obsidian points
 * at the Electron binary (obsidian.exe), never at node, so we spawn `node`
 * from PATH. DSH_NODE_BIN allows an explicit override.
 */
function nodeExecutable() {
  const override = process.env.DSH_NODE_BIN?.trim();
  if (override) return override;
  return process.platform === 'win32' ? 'node.exe' : 'node';
}

// ── dsh detection ───────────────────────────────────────────────────────────

function validInstallDir(dir) {
  if (!dir) return null;
  const tryRoot = (root) => {
    try {
      const manifest = JSON.parse(readFileSync(join(root, 'package.json'), 'utf8'));
      if (manifest.name !== '@deepseek-ai/dsh') return null;
      return { installDir: root, script: join(root, 'lib', 'bin.js') };
    } catch {
      return null;
    }
  };
  // npm-global layout: <dir> itself is @deepseek-ai/dsh
  const direct = tryRoot(dir);
  if (direct) return direct;
  // custom layout: <dir>/dsh is the package (e.g. E:\software\deepseek-harness)
  const nested = tryRoot(join(dir, 'dsh'));
  if (nested) return nested;
  return null;
}

function parseLauncher(cmdPath) {
  try {
    const content = readFileSync(cmdPath, 'utf8');
    const dp0 = dirname(cmdPath);
    const match = /node\s+"([^"]+)"/i.exec(content);
    if (match) {
      let script = match[1].trim();
      if (script.startsWith('%~dp0')) script = join(dp0, script.slice('%~dp0'.length));
      if (script.toLowerCase().endsWith('bin.js') || /lib[\\/]bin\.js/i.test(script)) {
        return { installDir: dirname(dirname(script)), script };
      }
    }
    if (/dsh[\\/]lib[\\/]bin\.js/.test(content)) {
      return { installDir: dp0, script: join(dp0, 'dsh', 'lib', 'bin.js') };
    }
    return { installDir: dp0, script: '' };
  } catch {
    return null;
  }
}

function detectInstallCandidates(settings) {
  const candidates = [];
  if (settings.dshInstallDir) candidates.push(settings.dshInstallDir);
  if (process.env.DSH_HOME) candidates.push(dirname(process.env.DSH_HOME));
  const appData = process.env.APPDATA || join(homedir(), 'AppData', 'Roaming');
  candidates.push(join(appData, 'npm', 'node_modules', '@deepseek-ai', 'dsh'));
  return candidates;
}

function detectFromShell() {
  const result = [];
  let command;
  if (process.platform === 'win32') {
    command = spawnSync('where', ['dsh'], { encoding: 'utf8', timeout: 6000, windowsHide: true });
  } else {
    command = spawnSync('which', ['dsh'], { encoding: 'utf8', timeout: 6000 });
  }
  if (command.status !== 0 || !command.stdout) return result;
  for (const raw of command.stdout.split(/\r?\n/)) {
    const line = raw.trim();
    if (line === '') continue;
    const parsed = parseLauncher(line);
    if (parsed) result.push(parsed);
    result.push({ installDir: dirname(line), script: '' });
  }
  return result;
}

function detectDsh(settings) {
  for (const dir of detectInstallCandidates(settings)) {
    const valid = validInstallDir(dir);
    if (valid) return valid;
  }
  for (const parsed of detectFromShell()) {
    const valid = validInstallDir(parsed.installDir);
    if (valid) return valid;
    if (parsed.script) return { installDir: parsed.installDir, script: parsed.script };
  }
  return null;
}

function detectDshHome(settings, detected) {
  if (settings.dshHome) return settings.dshHome;
  if (process.env.DSH_HOME) return process.env.DSH_HOME;
  if (detected?.installDir && existsSync(join(detected.installDir, '.dsh'))) {
    return join(detected.installDir, '.dsh');
  }
  return join(homedir(), '.dsh');
}

// ── dsh service manager ─────────────────────────────────────────────────────

class DshService {
  constructor(plugin) {
    this.plugin = plugin;
    this.child = null;
    this.status = 'unknown';
    this.logLines = [];
    this.listeners = new Set();
    this.cachedLocation = undefined;
  }

  onChange(listener) {
    this.listeners.add(listener);
    return () => this.listeners.delete(listener);
  }

  setStatus(status) {
    if (this.status === status) return;
    this.status = status;
    for (const listener of this.listeners) listener(status);
  }

  appendLog(text) {
    for (const line of String(text).split(/\r?\n/)) {
      if (line.trim() === '') continue;
      this.logLines.push(line);
      if (this.logLines.length > 200) this.logLines.shift();
    }
  }

  location(force = false) {
    if (!force && this.cachedLocation !== undefined) return this.cachedLocation;
    const detected = detectDsh(this.plugin.settings);
    this.cachedLocation = detected === null ? null : {
      installDir: detected.installDir,
      script: detected.script,
      home: detectDshHome(this.plugin.settings, detected)
    };
    return this.cachedLocation;
  }

  async ensureStarted() {
    if (await probeService(this.plugin.settings.port, 1200)) {
      this.setStatus('running');
      return;
    }
    return this.start();
  }

  async start() {
    if (this.child !== null && this.child.exitCode === null) return;
    if (await probeService(this.plugin.settings.port, 1200)) {
      this.setStatus('running');
      return;
    }
    const location = this.location();
    if (location === null) {
      this.setStatus('missing-dsh');
      throw new Error('dsh not found. Open the plugin settings, click “Detect dsh”, or install DeepSeek Harness first.');
    }
    const vaultPath = this.plugin.app.vault.adapter.getBasePath();
    const env = {
      ...process.env,
      DSH_HOME: location.home,
      DSH_OBSIDIAN_VAULT: vaultPath,
      DSH_SESSIONS_ROOT: join(location.home, 'sessions')
    };
    const args = location.script
      ? [location.script, '--profile', PRESET_NAME, '--port', String(this.plugin.settings.port)]
      : ['--profile', PRESET_NAME, '--port', String(this.plugin.settings.port)];
    const executable = location.script ? nodeExecutable() : 'dsh';
    // Without a resolved script we rely on the dsh launcher; Windows needs a
    // shell to execute .cmd shims.
    const shell = !location.script && process.platform === 'win32';
    this.setStatus('starting');
    this.appendLog(`starting: ${executable} ${args.join(' ')}`);
    this.child = spawn(executable, args, { env, windowsHide: true, shell, stdio: ['ignore', 'pipe', 'pipe'] });
    this.child.stdout.on('data', (chunk) => this.appendLog(chunk));
    this.child.stderr.on('data', (chunk) => this.appendLog(chunk));
    this.child.on('exit', (code) => {
      this.appendLog(`dsh exited with code ${code}`);
      this.child = null;
      if (this.status !== 'stopping') this.setStatus(code === 0 ? 'stopped' : 'error');
    });
    for (let attempt = 0; attempt < 60; attempt += 1) {
      await sleep(750);
      if (await probeService(this.plugin.settings.port, 1000)) {
        this.setStatus('running');
        return;
      }
      if (this.child === null || this.child.exitCode !== null) break;
    }
    this.setStatus('error');
    throw new Error(`dsh service did not come up on port ${this.plugin.settings.port}. ${this.logLines.slice(-3).join(' | ')}`);
  }

  async stop() {
    this.setStatus('stopping');
    const child = this.child;
    this.child = null;
    if (child !== null && child.exitCode === null) {
      child.kill();
      await sleep(600);
    }
    this.setStatus('stopped');
  }

  async restart() {
    await this.stop();
    await sleep(500);
    return this.start();
  }
}

// ── embedded configuration bootstrap ────────────────────────────────────────

function bootstrapDshConfig(plugin, force = false) {
  const location = plugin.service.location();
  if (location === null) throw new Error('dsh not detected; configure its install path in settings first.');
  const home = location.home;
  const presetRoot = join(home, '.agent-presets', PRESET_NAME);
  const profileRoot = join(home, 'profiles', PRESET_NAME);
  const written = [];

  // Code always refreshes; user-editable files are preserved unless forced.
  if (ensureFile(join(presetRoot, 'obsidian-memory.mjs'), EMBEDDED_PRESET['obsidian-memory.mjs'], true)) written.push('preset/obsidian-memory.mjs');
  if (ensureFile(join(presetRoot, 'preset.yml'), EMBEDDED_PRESET['preset.yml'], force)) written.push('preset/preset.yml');
  if (ensureFile(join(presetRoot, 'agent.cordis.yml'), EMBEDDED_PRESET['agent.cordis.yml'], force)) written.push('preset/agent.cordis.yml');
  if (ensureFile(join(profileRoot, 'package.json'), EMBEDDED_PRESET['profile-package.json'], force)) written.push('profile/package.json');
  if (ensureFile(join(profileRoot, 'cordis.yml'), EMBEDDED_PRESET['profile-cordis.yml'], true)) written.push('profile/cordis.yml');
  if (ensureFile(join(profileRoot, 'cordis.patch.yml'), EMBEDDED_PRESET['profile-cordis.patch.yml'], force)) written.push('profile/cordis.patch.yml');
  if (ensureFile(join(profileRoot, 'pnpm-workspace.yaml'), EMBEDDED_PRESET['profile-pnpm-workspace.yaml'], force)) written.push('profile/pnpm-workspace.yaml');
  return { home, written };
}

function bootstrapVaultTemplates(plugin, force = false) {
  const vault = plugin.app.vault.adapter.getBasePath();
  const mapping = [
    ['AGENTS.md', join(vault, 'AGENTS.md')],
    ['profile.md', join(vault, '.deepseek', 'memory', 'profile.md')],
    ['topics-index.md', join(vault, '.deepseek', 'memory', 'topics', 'index.md')],
    ['episodes-readme.md', join(vault, '.deepseek', 'memory', 'episodes', '_README.md')],
    ['episodes-index.md', join(vault, '.deepseek', 'memory', 'episodes', 'index.md')],
    ['inbox-readme.md', join(vault, '.deepseek', 'inbox', '_README.md')],
    ['inbox-index.md', join(vault, '.deepseek', 'inbox', 'index.md')]
  ];
  const written = [];
  for (const [key, target] of mapping) {
    if (ensureFile(target, EMBEDDED_TEMPLATES[key], force)) written.push(target);
  }
  return { vault, written };
}

// ── sidebar view ────────────────────────────────────────────────────────────

class DshMathView extends ItemView {
  constructor(leaf, plugin) {
    super(leaf);
    this.plugin = plugin;
    this.offStatus = null;
    this.iframe = null;
  }

  getViewType() {
    return VIEW_TYPE;
  }

  getDisplayText() {
    return 'DSH Math Assistant';
  }

  getIcon() {
    return 'message-square';
  }

  async onOpen() {
    this.contentEl.empty();
    this.contentEl.addClass('dsh-obsidian-math-view');
    this.statusRow = this.contentEl.createDiv({ cls: 'dsh-obsidian-math-status' });
    this.body = this.contentEl.createDiv({ cls: 'dsh-obsidian-math-body' });
    this.offStatus = this.plugin.service.onChange((status) => this.render(status));
    const status = await this.plugin.service.ensureStarted().then(() => this.plugin.service.status).catch(() => this.plugin.service.status);
    this.render(status);
  }

  render(status) {
    if (this.statusRow === undefined) return;
    if (status === 'running') {
      this.statusRow.empty();
      this.statusRow.style.display = 'none';
      if (this.iframe === null) {
        this.iframe = this.body.createEl('iframe', {
          cls: 'dsh-obsidian-math-iframe',
          attr: { src: `http://127.0.0.1:${this.plugin.settings.port}/` }
        });
      }
      return;
    }
    this.statusRow.style.display = '';
    if (this.iframe !== null) {
      this.iframe.remove();
      this.iframe = null;
    }
    this.statusRow.empty();
    const message = {
      starting: '正在启动 DeepSeek Harness 服务…',
      'missing-dsh': '未找到 dsh（DeepSeek Harness）。请打开插件设置并检测 dsh 安装路径。',
      error: 'dsh 服务启动失败。请打开插件设置查看日志。',
      stopped: 'dsh 服务已停止。',
      stopping: '正在停止服务…',
      unknown: '服务状态未知。'
    }[status] ?? '服务状态未知。';
    this.statusRow.setText(message);
    const actions = this.statusRow.createDiv({ cls: 'dsh-obsidian-math-actions' });
    const retry = actions.createEl('button', { text: '重试' });
    retry.addEventListener('click', async () => {
      this.render('starting');
      await this.plugin.service.ensureStarted().catch((error) => new Notice(String(error)));
      this.render(this.plugin.service.status);
    });
    const settings = actions.createEl('button', { text: '打开设置' });
    settings.addEventListener('click', () => this.plugin.openSettings());
  }

  async onClose() {
    if (this.offStatus !== null) this.offStatus();
  }
}

// ── plugin ──────────────────────────────────────────────────────────────────

class DshObsidianMathPlugin extends Plugin {
  async onload() {
    await this.loadSettings();
    this.service = new DshService(this);
    this.registerView(VIEW_TYPE, (leaf) => new DshMathView(leaf, this));
    if (this.settings.showRibbon) {
      this.addRibbonIcon('message-square', 'Open DSH Math Assistant', () => this.activateView());
    }
    this.addCommand({
      id: 'open-dsh-math-assistant',
      name: 'Open DSH Math Assistant',
      callback: () => this.activateView()
    });
    this.addCommand({
      id: 'start-dsh-service',
      name: 'Start DSH service',
      callback: async () => {
        try {
          await this.service.start();
          new Notice('DSH service running');
        } catch (error) {
          new Notice(String(error));
        }
      }
    });
    this.addCommand({
      id: 'stop-dsh-service',
      name: 'Stop DSH service',
      callback: async () => {
        await this.service.stop();
        new Notice('DSH service stopped');
      }
    });
    this.addSettingTab(new DshObsidianSettingTab(this.app, this));
    if (this.settings.autoInit) {
      this.app.workspace.onLayoutReady(() => {
        try {
          bootstrapDshConfig(this, false);
          bootstrapVaultTemplates(this, false);
        } catch (error) {
          new Notice(`dsh-obsidian-math: ${String(error)}`);
        }
      });
    }
    if (this.settings.autoStart) {
      this.app.workspace.onLayoutReady(() => {
        setTimeout(() => {
          this.service.ensureStarted().catch(() => {});
        }, 1200);
      });
    }
  }

  async activateView() {
    const { workspace } = this.app;
    let leaf = workspace.getLeavesOfType(VIEW_TYPE)[0];
    if (!leaf) {
      if (typeof workspace.getRightLeaf === 'function') {
        leaf = workspace.getRightLeaf(false);
      } else {
        leaf = workspace.getLeaf('tab');
      }
      await leaf.setViewState({ type: VIEW_TYPE, active: true });
    }
    if (typeof workspace.revealLeaf === 'function') await workspace.revealLeaf(leaf);
    else workspace.setActiveLeaf(leaf);
  }

  openSettings() {
    const setting = this.app.setting;
    if (!setting) return;
    try {
      setting.open();
    } catch {
      // ignored; openTabById below is the important part
    }
    try {
      setting.openTabById('dsh-obsidian-math');
    } catch {
      // older Obsidian: the settings root is already open
    }
  }

  async loadSettings() {
    this.settings = Object.assign({}, DEFAULT_SETTINGS, await this.loadData());
  }

  async saveSettings() {
    await this.saveData(this.settings);
  }

  onunload() {
    if (this.service?.child !== null && !this.settings.keepAliveOnUnload) {
      this.service?.stop();
    }
  }
}

module.exports = DshObsidianMathPlugin;

// ── settings tab ────────────────────────────────────────────────────────────

class DshObsidianSettingTab extends PluginSettingTab {
  constructor(app, plugin) {
    super(app, plugin);
    this.plugin = plugin;
  }

  display() {
    const { containerEl } = this;
    containerEl.empty();
    containerEl.createEl('h2', { text: 'DSH Obsidian Math Assistant' });
    containerEl.createEl('p', { text: `Version ${this.plugin.manifest?.version ?? ''}` });
    containerEl.createEl('p', { text: 'Embeds the DeepSeek Harness math-memory agent in the right sidebar. The plugin starts the dsh service automatically; no extra cmd window is needed.' });

    new Setting(containerEl)
      .setName('Port')
      .setDesc('Local port for the dsh web service.')
      .addText((text) => text
        .setPlaceholder('3180')
        .setValue(String(this.plugin.settings.port))
        .onChange(async (value) => {
          const port = Number.parseInt(value, 10);
          if (Number.isInteger(port) && port > 0 && port < 65536) {
            this.plugin.settings.port = port;
            await this.plugin.saveSettings();
          }
        }));

    const location = this.plugin.service.location();
    new Setting(containerEl)
      .setName('dsh installation directory')
      .setDesc(location ? `Detected: ${location.installDir}` : 'Not detected yet. Click Detect or enter the path manually.')
      .addText((text) => text
        .setPlaceholder('e.g. E:\\software\\deepseek-harness')
        .setValue(this.plugin.settings.dshInstallDir)
        .onChange(async (value) => {
          this.plugin.settings.dshInstallDir = value.trim();
          this.plugin.service.cachedLocation = undefined;
          await this.plugin.saveSettings();
        }))
      .addButton((button) => button.setButtonText('Detect').onClick(async () => {
        const found = this.plugin.service.location(true);
        if (found === null) {
          new Notice('dsh not found on PATH or in common locations. Install DeepSeek Harness, then enter its directory manually.');
        } else {
          this.plugin.settings.dshInstallDir = found.installDir;
          await this.plugin.saveSettings();
          new Notice(`Detected dsh at ${found.installDir}`);
          this.display();
        }
      }));

    new Setting(containerEl)
      .setName('DSH_HOME')
      .setDesc('Harness home directory (presets, profiles, sessions).')
      .addText((text) => text
        .setPlaceholder(location?.home ?? '')
        .setValue(this.plugin.settings.dshHome)
        .onChange(async (value) => {
          this.plugin.settings.dshHome = value.trim();
          this.plugin.service.cachedLocation = undefined;
          await this.plugin.saveSettings();
        }));

    new Setting(containerEl)
      .setName('Start service automatically')
      .setDesc('Start the dsh service when Obsidian loads.')
      .addToggle((toggle) => toggle.setValue(this.plugin.settings.autoStart).onChange(async (value) => {
        this.plugin.settings.autoStart = value;
        await this.plugin.saveSettings();
      }));

    new Setting(containerEl)
      .setName('Initialize configuration automatically')
      .setDesc('Create the dsh preset/profile and vault memory templates when missing (first run only).')
      .addToggle((toggle) => toggle.setValue(this.plugin.settings.autoInit).onChange(async (value) => {
        this.plugin.settings.autoInit = value;
        await this.plugin.saveSettings();
      }));

    new Setting(containerEl)
      .setName('Show ribbon icon')
      .setDesc('One-click button in the Obsidian ribbon.')
      .addToggle((toggle) => toggle.setValue(this.plugin.settings.showRibbon).onChange(async (value) => {
        this.plugin.settings.showRibbon = value;
        await this.plugin.saveSettings();
      }));

    new Setting(containerEl)
      .setName('Keep service alive when Obsidian closes')
      .setDesc('By default the plugin stops its own dsh child process on unload.')
      .addToggle((toggle) => toggle.setValue(this.plugin.settings.keepAliveOnUnload).onChange(async (value) => {
        this.plugin.settings.keepAliveOnUnload = value;
        await this.plugin.saveSettings();
      }));

    containerEl.createEl('h3', { text: 'Configuration' });
    const configRow = containerEl.createDiv({ cls: 'dsh-obsidian-math-config-actions' });
    const initButton = configRow.createEl('button', { text: 'Initialize dsh + vault templates' });
    initButton.addEventListener('click', async () => {
      try {
        const dsh = bootstrapDshConfig(this.plugin, false);
        const vault = bootstrapVaultTemplates(this.plugin, false);
        new Notice(`dsh config ready (${dsh.written.length} files). Vault templates: ${vault.written.length} created/updated.`);
        this.display();
      } catch (error) {
        new Notice(String(error));
      }
    });
    const forceButton = configRow.createEl('button', { text: 'Reinstall dsh config (force)' });
    forceButton.addEventListener('click', async () => {
      try {
        const result = bootstrapDshConfig(this.plugin, true);
        new Notice(`dsh config reinstalled at ${result.home}`);
        this.display();
      } catch (error) {
        new Notice(String(error));
      }
    });

    containerEl.createEl('h3', { text: 'Service' });
    const serviceRow = containerEl.createDiv({ cls: 'dsh-obsidian-math-config-actions' });
    const startButton = serviceRow.createEl('button', { text: 'Start service' });
    startButton.addEventListener('click', async () => {
      await this.plugin.service.start().catch((error) => new Notice(String(error)));
      this.display();
    });
    const stopButton = serviceRow.createEl('button', { text: 'Stop service' });
    stopButton.addEventListener('click', async () => {
      await this.plugin.service.stop();
      this.display();
    });
    const restartButton = serviceRow.createEl('button', { text: 'Restart service' });
    restartButton.addEventListener('click', async () => {
      await this.plugin.service.restart().catch((error) => new Notice(String(error)));
      this.display();
    });
    const status = serviceRow.createEl('span', { text: ` status: ${this.plugin.service.status}` });

    const log = this.plugin.service.logLines.slice(-12).join('\n');
    if (log !== '') {
      containerEl.createEl('h3', { text: 'Recent service log' });
      containerEl.createEl('pre', { text: log, cls: 'dsh-obsidian-math-log' });
    }
  }
}
